/*
 * A285519  Positions of 0 in A285518; complement of A285520.
 * https://oeis.org/A285519
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = position of the n‑th 0 in the word generated by the
 *            morphism 0→11, 1→0101 starting from the symbol 1. Computing this
 *            uses a linear probe of the word; the word is interpreted via a
 *            backward depth‑wise walk that starts at an even depth,
 *            guaranteeing that the returned letter is the one that s...
 * Range:     u8 n <= 96, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>

static idx_t len0[64];
static idx_t len1[64];
static int len_initialized = 0;

static void init_lengths(void)
{
    if (len_initialized) return;
    len0[0] = 1;
    len1[0] = 1;
    for (size_t d = 1; d < 64; ++d) {
        /* 0 → 11  (two 1’s) */
        len0[d] = 2 * len1[d - 1];
        /* 1 → 0101 (two 0’s and two 1’s) */
        len1[d] = 2 * (len0[d - 1] + len1[d - 1]);
    }
    len_initialized = 1;
}

/* Letter (0 or 1) at position pos (1‑based) in the limit word.
   The chosen even depth ensures that the letter has stabilised
   on all subsequent even depths. */
static int bit_at(idx_t pos)
{
    init_lengths();

    size_t depth = 0;
    while (len1[depth] < pos) ++depth;
    if (depth & 1) ++depth;          /* make depth even */

    idx_t index = pos;
    int letter = 1;      /* initial symbol */

    while (depth > 0) {
        if (letter == 0) {
            idx_t block = len1[depth - 1];   /* 0 → 11 */
            if (index > block) index -= block;
            letter = 1;
        } else {             /* letter == 1 */
            idx_t block0 = len0[depth - 1]; /* 1 → 0101 : first 0 */
            idx_t block1 = len1[depth - 1]; /*          first 1 */
            if (index <= block0) {
                letter = 0;
            } else if (index <= block0 + block1) {
                index -= block0;
                letter = 1;
            } else if (index <= block0 + block1 + block0) {
                index -= block0 + block1;
                letter = 0;
            } else {
                index -= block0 + block1 + block0;
                letter = 1;
            }
        }
        --depth;
    }
    return letter;
}

seq_t a(idx_t n)
{
    idx_t zeros_seen = 0;
    idx_t pos = 1;          /* positions are 1‑based */

    for (;;) {
        if (bit_at(pos) == 0) {
            ++zeros_seen;
            if (zeros_seen == n)
                return (seq_t)pos;
        }
        ++pos;
    }
}
